// 테스트용: 샘플 시술기록이 안에 들어 있음 (실제 운영 땐 구글시트에서 읽음)
const WEEKS=5;
const recs=[
 {고객명:'김서연',연락처:'010-4521-7733',이용일:'2026-10-03',시술:'하어스 펌',상태:'이용완료'},
 {고객명:'이지우',연락처:'010-8830-2191',이용일:'2026-10-05',시술:'클래식 연장',상태:'이용완료'},
 {고객명:'박하은',연락처:'010-2290-6614',이용일:'2026-10-08',시술:'하어스 클리닉 펌',상태:'이용완료'},
 {고객명:'최민서',연락처:'010-7712-3350',이용일:'2026-10-09',시술:'마스카라 연장',상태:'취소'},
 {고객명:'정서현',연락처:'010-3390-8821',이용일:'2026-10-11',시술:'하어스 펌',상태:'이용완료'},
 {고객명:'강지민',연락처:'010-5566-1023',이용일:'2026-10-12',시술:'펌 포인트 연장',상태:'노쇼'},
 {고객명:'조수아',연락처:'010-9012-4477',이용일:'2026-11-02',시술:'하어스 펌',상태:'이용완료'},
 {고객명:'윤예은',연락처:'010-6678-9034',이용일:'2026-11-08',시술:'클래식 연장',상태:'이용완료'},
 {고객명:'김서연',연락처:'010-4521-7733',이용일:'2026-11-12',시술:'하어스 펌',상태:'이용완료'},
];
const today=new Date();today.setHours(0,0,0,0);
const skip=/취소|노쇼/;const cust={};
for(const r of recs){
  if(skip.test(r.상태))continue;
  const k=r.고객명+'|'+r.연락처;
  const c=cust[k]||(cust[k]={name:r.고객명,phone:r.연락처,visits:0,last:'',lastService:''});
  c.visits++; if(r.이용일>c.last){c.last=r.이용일;c.lastService=r.시술}
}
const out=[];
for(const c of Object.values(cust)){
  const days=Math.floor((today-new Date(c.last))/86400000);
  if(days<WEEKS*7)continue;
  const weeks=Math.floor(days/7);
  const draft=`${c.name}님 안녕하세요, 하어스예요 :)\n${c.lastService} 받으신 지 ${weeks}주 정도 지났어요. 컬이 풀리거나 숱이 빠질 때라 리터치 생각나시면 편하게 연락 주세요.\n이번 주 예약 가능한 시간 안내드릴게요!`;
  out.push({json:{...c,weeks,tg:`👁 ${c.name}님 · ${c.lastService} · ${weeks}주 전 방문 (총 ${c.visits}회)\n연락처 ${c.phone}\n\n${draft}`}});
}
return out;
